tools.example:
set want 2024.2
if {[version -short] ne $want} {
  error "This project requires Vivado $want, running [version -short]"
}
puts [version]

tools.usage:
Block/Distributed memory:
memory_initialization_radix=16;
memory_initialization_vector=
0000, 0001, 00FF, ... ;
FIR Compiler:
radix=10;
coefdata= -12, 0, 87, 256, 87, 0, -12;
IP parameter: CONFIG.Coe_File (Load_Init_File true) / CONFIG.CoefficientSource COE_File

UCF:  NET "clk" LOC = "E3" | IOSTANDARD = LVCMOS33;
      NET "clk" TNM_NET = sys_clk; TIMESPEC TS_sys_clk = PERIOD "sys_clk" 10 ns HIGH 50%;
XDC:  set_property -dict {PACKAGE_PIN E3 IOSTANDARD LVCMOS33} [get_ports clk]
      create_clock -period 10.000 -name sys_clk [get_ports clk]
